-- READ ONLY. Run in the selected QA project vhnkezwjknwpddqhlnfk.
-- No credentials, tokens, customer rows or coordinates are returned.
select jsonb_build_object(
 'database',current_database(),
 'auth_session_columns',(select jsonb_agg(column_name order by column_name) from information_schema.columns where table_schema='auth' and table_name='sessions' and column_name in ('id','user_id','not_after')),
 'auth_jwt_exists',to_regprocedure('auth.jwt()') is not null,
 'extensions',(select jsonb_agg(jsonb_build_object('name',extname,'schema',n.nspname)) from pg_extension e join pg_namespace n on n.oid=e.extnamespace where extname in ('postgis','pgcrypto')),
 'push_functions',(select coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'))),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('register_interest_push_device','revoke_interest_push_device','verify_interest_push','publish_route_location','claim_interest_push_job','interest_push_job_binding','interest_push_job_eligible','finish_interest_push_job','retry_interest_push_job','invalidate_interest_push_device')),
 'private_tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'authenticated_select',has_table_privilege('authenticated',c.oid,'SELECT'),'service_select',has_table_privilege('service_role',c.oid,'SELECT'))),'[]'::jsonb) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('interest_push_devices','interest_push_progress','interest_push_revocations','interest_push_outbox')),
 'trigger_bindings',(select jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'trigger',t.tgname,'function',fn.nspname||'.'||p.proname,'enabled',t.tgenabled,'definition',case when t.tgnargs=0 and t.tgqual is null then pg_get_triggerdef(t.oid,true) end)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid join pg_namespace fn on fn.oid=p.pronamespace where not t.tgisinternal and ((n.nspname='auth' and c.relname='users') or (n.nspname='public' and c.relname in ('vendor_routes','purchase_intents')))),
 'qa_route_shape',(select jsonb_build_object('exists',true,'status',r.status,'points',jsonb_array_length(r.waypoints),'points_have_order',not exists(select 1 from jsonb_array_elements(r.waypoints) p where not(p?'orderIndex')),'max_distance_from_first_m',(select max(extensions.st_distance(extensions.st_setsrid(extensions.st_makepoint((p->>'longitude')::float8,(p->>'latitude')::float8),4326)::extensions.geography,extensions.st_setsrid(extensions.st_makepoint((r.waypoints->0->>'longitude')::float8,(r.waypoints->0->>'latitude')::float8),4326)::extensions.geography)) from jsonb_array_elements(r.waypoints) p)) from public.vendor_routes r where r.id='00000000-0000-4000-8000-000000000003')
) as rc1_preflight;
